/**
 * Tearsheet 2.0 — runtime
 *
 * Reads window.__PKTS_MANIFEST__ (injected by manifest.js, generated by
 * scripts/generate-manifest.mjs) and builds a single-page component playground.
 * Loaded as type="module" so it executes after dist/esm/bundle.js (which
 * registers the custom elements).
 *
 * Props form: schema-driven via renderForm() from form.js.
 * Code snippet: pkts-code with type="block" language="html"; updated by
 * setting the `code` attribute — never recreated.
 *
 * Availability values:
 *   "html-native"  — no web component; native tags styled by Packets defaults.
 *   "ui-css"       — native element + pkts- class(es). Web component may exist.
 *   "web"          — web component only.
 */

import { renderForm } from '../form.js';

// ── Helpers ───────────────────────────────────────────────────────────────────

function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escContent(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'className') node.className = v;
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2).toLowerCase(), v);
    else node.setAttribute(k, v);
  }
  for (const child of children) {
    if (child == null) continue;
    node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return node;
}

/** Sync dark/palette classes from body to a preview container. */
function syncThemeClasses(container) {
  document.body.classList.forEach(cls => {
    if (cls === 'dark' || cls.startsWith('palette-')) container.classList.add(cls);
  });
}

// ── Code snippet ──────────────────────────────────────────────────────────────

function generateSnippet(comp, state, slotContent) {
  const outerTag = comp.customElementExtends || comp.tagName;
  const isAttr   = comp.customElementExtends ? ` is="${comp.tagName}"` : '';

  let attrStr = '';
  for (const prop of comp.props) {
    if (prop.kind === 'event') continue;
    const val = state[prop.attrName];
    if (val === null || val === undefined) continue;

    if (prop.kind === 'boolean') {
      if (prop.booleanStyle === 'false-string') {
        attrStr += ` ${prop.attrName}="${val ? 'true' : 'false'}"`;
      } else if (val) {
        attrStr += ` ${prop.attrName}`;
      }
    } else if (val !== '') {
      attrStr += ` ${prop.attrName}="${esc(String(val))}"`;
    }
  }

  return `<${outerTag}${isAttr}${attrStr}>${escContent(slotContent)}</${outerTag}>`;
}

// ── Apply state to preview element ───────────────────────────────────────────

function applyPropToEl(el, prop, value) {
  if (value === null || value === undefined) {
    el.removeAttribute(prop.attrName);
    return;
  }
  if (prop.kind === 'boolean') {
    if (prop.booleanStyle === 'false-string') {
      el.setAttribute(prop.attrName, value ? 'true' : 'false');
    } else {
      if (prop.name in el) { try { el[prop.name] = !!value; return; } catch {} }
      el.toggleAttribute(prop.attrName, !!value);
    }
  } else {
    if (prop.name in el) { try { el[prop.name] = value; return; } catch {} }
    el.setAttribute(prop.attrName, String(value));
  }
}

function applyStateToEl(previewEl, comp, state) {
  for (const prop of comp.props) {
    if (prop.kind === 'event') continue;
    applyPropToEl(previewEl, prop, state[prop.attrName] ?? null);
  }
}

function seedState(comp) {
  const state = {};
  for (const prop of comp.props) {
    if (prop.kind === 'event') continue;
    if (prop.kind === 'union' && prop.allowedValues?.length) {
      state[prop.attrName] = prop.allowedValues[0];
    } else if (!prop.optional) {
      if (prop.kind === 'string')   state[prop.attrName] = prop.name;
      else if (prop.kind === 'number')  state[prop.attrName] = '0';
      else if (prop.kind === 'boolean') state[prop.attrName] = false;
    }
  }
  return state;
}

// ── Preview mounting ──────────────────────────────────────────────────────────

function createPreviewEl(comp) {
  if (comp.customElementExtends) {
    const e = document.createElement(comp.customElementExtends);
    e.setAttribute('is', comp.tagName);
    return e;
  }
  return document.createElement(comp.tagName);
}

function mountPreview(sandbox, comp, state, slotContent) {
  sandbox.innerHTML = '';
  const e = createPreviewEl(comp);
  if (slotContent) e.appendChild(document.createTextNode(slotContent));
  sandbox.appendChild(e);
  applyStateToEl(e, comp, state);
  return e;
}

// ── Figma panel ───────────────────────────────────────────────────────────────

function buildFigmaPanel(figmaEntry, componentName) {
  const aside = document.createElement('aside');
  aside.className = 'demo-figma';

  const label = document.createElement('div');
  label.className = 'demo-label';
  label.textContent = 'Figma';

  const container = document.createElement('div');
  container.className = 'figma-embed';

  if (Array.isArray(figmaEntry.size) && figmaEntry.size.length === 2) {
    container.style.setProperty('--figma-ratio', String(figmaEntry.size[0] / figmaEntry.size[1]));
  }

  const iframe = document.createElement('iframe');
  iframe.src            = figmaEntry.url;
  iframe.title          = figmaEntry.title || `${componentName} in Figma`;
  iframe.loading        = 'lazy';
  iframe.allowFullscreen = true;

  container.appendChild(iframe);
  aside.append(label, container);
  return aside;
}

// ── Helper: apply a modifier class to the root element of CSS markup ──────────

function applyCssVariant(baseMarkup, variantClass) {
  if (!variantClass) return baseMarkup;
  const tmp = document.createElement('div');
  tmp.innerHTML = baseMarkup;
  const root = tmp.firstElementChild;
  if (root) root.classList.add(variantClass);
  return tmp.innerHTML;
}

// ── Split layout helper ───────────────────────────────────────────────────────

function buildSplitLayout(panel, comp) {
  const hasFigma = !!(comp.figma && comp.figma.url);
  if (hasFigma) {
    const split = document.createElement('div');
    split.className = 'ts2-panel-split';
    const mainCol = document.createElement('div');
    mainCol.className = 'ts2-panel-main';
    split.appendChild(mainCol);
    split.appendChild(buildFigmaPanel(comp.figma, comp.displayName));
    panel.appendChild(split);
    return mainCol;
  }
  return panel;
}

// ── HTML-native panel ─────────────────────────────────────────────────────────
// No web component; bare native tags styled by Packets CSS defaults.

function renderHtmlNativePanel(comp) {
  const panel = document.getElementById('ts2-panel');
  panel.innerHTML = '';

  const header = document.createElement('div');
  header.className = 'ts2-comp-header';
  const title = document.createElement('h1');
  title.className   = 'ts2-comp-name';
  title.textContent = comp.displayName;
  header.appendChild(title);

  const note = document.createElement('p');
  note.className   = 'ts2-css-note';
  note.textContent = 'Native HTML styled by Packets defaults. No web component or classes needed.';
  header.appendChild(note);

  panel.appendChild(header);

  if (comp.noDemo) {
    const nodemo = document.createElement('div');
    nodemo.className = 'ts2-no-types';
    nodemo.innerHTML = `<strong>No demo available.</strong>&nbsp; Add an entry to <code>tearsheet-2/native-markup.json</code> to show a live preview.`;
    panel.appendChild(nodemo);
    return;
  }

  const mainCol = buildSplitLayout(panel, comp);

  const variants = comp.variants;
  let currentMarkup = variants ? variants[0].markup : (comp.markup || '');

  if (variants && variants.length > 1) {
    const variantRow = document.createElement('div');
    variantRow.className = 'ts2-variant-row';
    const lbl = document.createElement('label');
    lbl.className   = 'ts2-section-title';
    lbl.textContent = 'Variant';
    const sel = document.createElement('select');
    sel.className = 'ts2-variant-select';
    variants.forEach((v, i) => {
      const o = document.createElement('option');
      o.value = String(i);
      o.textContent = v.label;
      sel.appendChild(o);
    });
    sel.addEventListener('change', () => {
      currentMarkup = variants[Number(sel.value)].markup;
      renderMarkup();
      updateSnippet();
    });
    variantRow.appendChild(lbl);
    variantRow.appendChild(sel);
    mainCol.appendChild(variantRow);
  }

  const previewWrap = document.createElement('div');
  previewWrap.appendChild(el('h2', { className: 'ts2-section-title' }, 'Preview'));
  const sandbox = document.createElement('div');
  sandbox.className = 'packets ts2-preview';
  sandbox.dataset.preview = comp.id;
  syncThemeClasses(sandbox);
  previewWrap.appendChild(sandbox);
  mainCol.appendChild(previewWrap);

  function renderMarkup() { sandbox.innerHTML = currentMarkup; }
  renderMarkup();

  const snippetSection = document.createElement('div');
  snippetSection.className = 'ts2-snippet-section';
  snippetSection.appendChild(el('h2', { className: 'ts2-section-title' }, 'Code'));

  const codeEl = document.createElement('pkts-code');
  codeEl.setAttribute('type', 'block');
  codeEl.setAttribute('language', 'html');
  codeEl.setAttribute('code', currentMarkup);
  snippetSection.appendChild(codeEl);

  function updateSnippet() { codeEl.setAttribute('code', currentMarkup); }

  mainCol.appendChild(snippetSection);
}

