// ── ui-css (with web component) panel ────────────────────────────────────────
// Web preview + props form + two snippets (web component & CSS classes) + CSS preview.

function renderUiCssWebPanel(comp) {
  const panel = document.getElementById('ts2-panel');
  panel.innerHTML = '';

  // Header
  const header = document.createElement('div');
  header.className = 'ts2-comp-header';
  const title = document.createElement('h1');
  title.className   = 'ts2-comp-name';
  title.textContent = comp.displayName;
  const tagCode = document.createElement('code');
  tagCode.className   = 'ts2-tag-name';
  tagCode.textContent = comp.customElementExtends
    ? `<${comp.customElementExtends} is="${comp.tagName}">`
    : `<${comp.tagName}>`;
  header.appendChild(title);
  header.appendChild(tagCode);
  panel.appendChild(header);

  const mainCol = buildSplitLayout(panel, comp);

  // No-types notice
  if (!comp.hasTypesFile) {
    const notice = document.createElement('div');
    notice.className = 'ts2-no-types';
    notice.innerHTML =
      `<strong>No types file.</strong>&nbsp; Add <code>${comp.className}.types.ts</code> to get prop controls.`;
    mainCol.appendChild(notice);
    if (comp.observedAttributes.length) {
      const attrs = document.createElement('p');
      attrs.className = 'ts2-obs-attrs';
      attrs.innerHTML = `Observed attributes: ${comp.observedAttributes.map(a => `<code>${a}</code>`).join(', ')}`;
      mainCol.appendChild(attrs);
    }
  }

  // State
  const state = seedState(comp);
  let slotContent = '';
  if (comp.hasSlot) state['content'] = '';

  // Web component preview
  const previewWrap = document.createElement('div');
  previewWrap.appendChild(el('h2', { className: 'ts2-section-title' }, 'Preview'));
  const sandbox = document.createElement('div');
  sandbox.className  = 'ts2-preview';
  sandbox.dataset.preview = comp.tagName;
  previewWrap.appendChild(sandbox);
  mainCol.appendChild(previewWrap);

  let previewEl = mountPreview(sandbox, comp, state, slotContent);

  // Web component snippet element
  const webCodeEl = document.createElement('pkts-code');
  webCodeEl.setAttribute('type', 'block');
  webCodeEl.setAttribute('language', 'html');
  webCodeEl.setAttribute('code', generateSnippet(comp, state, slotContent));

  function updateWebSnippet() {
    webCodeEl.setAttribute('code', generateSnippet(comp, state, slotContent));
  }

  // Controls — schema-driven form
  const controlsSection = document.createElement('div');
  controlsSection.className = 'ts2-controls';

  if (comp.hasTypesFile && comp.schema) {
    const form = renderForm(comp.schema, state, (key, newVal) => {
      if (key === 'content') {
        slotContent = newVal ?? '';
        previewEl = mountPreview(sandbox, comp, state, slotContent);
      } else {
        const prop = comp.props.find(p => p.attrName === key || p.name === key);
        if (newVal === null || newVal === undefined) {
          delete state[key];
          if (prop) applyPropToEl(previewEl, prop, null);
          else previewEl.removeAttribute(key);
        } else {
          state[key] = newVal;
          if (prop) applyPropToEl(previewEl, prop, newVal);
          else previewEl.setAttribute(key, String(newVal));
        }
      }
      updateWebSnippet();
    });
    controlsSection.appendChild(form);

    if (comp.events && comp.events.length) {
      const evtSection = document.createElement('div');
      evtSection.className = 'ts2-events-list';
      const evtTitle = document.createElement('h3');
      evtTitle.className = 'ts2-section-subtitle';
      evtTitle.textContent = 'Events';
      evtSection.appendChild(evtTitle);
      for (const evt of comp.events) {
        const row = document.createElement('div');
        row.className = 'ts2-event-field';
        const lbl = document.createElement('span');
        lbl.className = 'ts2-event-label';
        lbl.textContent = evt.name;
        row.appendChild(lbl);
        if (evt.description) {
          const desc = document.createElement('span');
          desc.className = 'ts2-event-value';
          desc.textContent = evt.description;
          row.appendChild(desc);
        }
        evtSection.appendChild(row);
      }
      controlsSection.appendChild(evtSection);
    }

    const resetBtn = document.createElement('pkts-button');
    resetBtn.setAttribute('label', 'Reset to defaults');
    resetBtn.setAttribute('variant', 'default');
    resetBtn.addEventListener('click', () => renderPanel(comp));
    controlsSection.appendChild(resetBtn);
  }

  mainCol.appendChild(controlsSection);

  // ── Two snippets ──────────────────────────────────────────────────────────

  const snippetsSection = document.createElement('div');
  snippetsSection.className = 'ts2-snippet-section';

  // 1. Web component snippet
  const webSnippetLabel = document.createElement('div');
  webSnippetLabel.className = 'ts2-snippet-label';
  webSnippetLabel.textContent = 'Web component';
  snippetsSection.appendChild(webSnippetLabel);
  snippetsSection.appendChild(webCodeEl);

  // 2. CSS classes snippet with optional variant select + live CSS preview
  const cssSnippetLabel = document.createElement('div');
  cssSnippetLabel.className = 'ts2-snippet-label';
  cssSnippetLabel.textContent = 'CSS classes';
  snippetsSection.appendChild(cssSnippetLabel);

  let cssVariantClass = '';

  const cssCodeEl = document.createElement('pkts-code');
  cssCodeEl.setAttribute('type', 'block');
  cssCodeEl.setAttribute('language', 'html');
  cssCodeEl.setAttribute('code', comp.cssMarkup || '');

  if (comp.cssVariants && comp.cssVariants.length) {
    const variantRow = document.createElement('div');
    variantRow.className = 'ts2-variant-row';
    const lbl = document.createElement('label');
    lbl.className   = 'ts2-section-title';
    lbl.textContent = 'Modifier class';
    const sel = document.createElement('select');
    sel.className = 'ts2-variant-select';
    const defaultOpt = document.createElement('option');
    defaultOpt.value = '';
    defaultOpt.textContent = '— none —';
    sel.appendChild(defaultOpt);
    for (const cls of comp.cssVariants) {
      const o = document.createElement('option');
      o.value = cls;
      o.textContent = cls;
      sel.appendChild(o);
    }
    sel.addEventListener('change', () => {
      cssVariantClass = sel.value;
      const markup = applyCssVariant(comp.cssMarkup, cssVariantClass);
      cssCodeEl.setAttribute('code', markup);
      cssPreview.innerHTML = markup;
    });
    variantRow.appendChild(lbl);
    variantRow.appendChild(sel);
    snippetsSection.appendChild(variantRow);
  }

  snippetsSection.appendChild(cssCodeEl);

  // CSS preview — mirrors body's dark/palette state; must contain no pkts-* elements
  const cssPreviewLabel = document.createElement('div');
  cssPreviewLabel.className = 'ts2-snippet-label';
  cssPreviewLabel.textContent = 'CSS preview';
  snippetsSection.appendChild(cssPreviewLabel);

  const cssPreview = document.createElement('div');
  cssPreview.className = 'packets ts2-css-preview';
  syncThemeClasses(cssPreview);
  cssPreview.innerHTML = comp.cssMarkup || '';
  snippetsSection.appendChild(cssPreview);

  mainCol.appendChild(snippetsSection);
}

// ── Web-only panel ────────────────────────────────────────────────────────────

function renderWebPanel(comp) {
  const panel = document.getElementById('ts2-panel');
  panel.innerHTML = '';

  // Header
  const header  = document.createElement('div');
  header.className = 'ts2-comp-header';
  const title   = document.createElement('h1');
  title.className   = 'ts2-comp-name';
  title.textContent = comp.displayName;
  const tagCode = document.createElement('code');
  tagCode.className   = 'ts2-tag-name';
  tagCode.textContent = comp.customElementExtends
    ? `<${comp.customElementExtends} is="${comp.tagName}">`
    : `<${comp.tagName}>`;
  header.appendChild(title);
  header.appendChild(tagCode);
  panel.appendChild(header);

  const mainCol = buildSplitLayout(panel, comp);

  // No-types notice
  if (!comp.hasTypesFile) {
    const notice = document.createElement('div');
    notice.className = 'ts2-no-types';
    notice.innerHTML =
      `<strong>No types file.</strong>&nbsp; Add <code>${comp.className}.types.ts</code> to get prop controls.`;
    mainCol.appendChild(notice);
    if (comp.observedAttributes.length) {
      const attrs = document.createElement('p');
      attrs.className = 'ts2-obs-attrs';
      attrs.innerHTML = `Observed attributes: ${comp.observedAttributes.map(a => `<code>${a}</code>`).join(', ')}`;
      mainCol.appendChild(attrs);
    }
  }

  // State
  const state = seedState(comp);
  let slotContent = '';
  if (comp.hasSlot) state['content'] = '';

  // Preview sandbox
  const previewWrap = document.createElement('div');
  previewWrap.appendChild(el('h2', { className: 'ts2-section-title' }, 'Preview'));
  const sandbox = document.createElement('div');
  sandbox.className  = 'ts2-preview';
  sandbox.dataset.preview = comp.tagName;
  previewWrap.appendChild(sandbox);
  mainCol.appendChild(previewWrap);

  let previewEl = mountPreview(sandbox, comp, state, slotContent);

  // Code snippet
  const snippetSection = document.createElement('div');
  snippetSection.className = 'ts2-snippet-section';
  snippetSection.appendChild(el('h2', { className: 'ts2-section-title' }, 'Code'));

  const codeEl = document.createElement('pkts-code');
  codeEl.setAttribute('type', 'block');
  codeEl.setAttribute('language', 'html');
  codeEl.setAttribute('code', generateSnippet(comp, state, slotContent));
  snippetSection.appendChild(codeEl);

  function updateSnippet() {
    codeEl.setAttribute('code', generateSnippet(comp, state, slotContent));
  }

  // Controls
  const controlsSection = document.createElement('div');
  controlsSection.className = 'ts2-controls';

  if (comp.hasTypesFile && comp.schema) {
    const form = renderForm(comp.schema, state, (key, newVal) => {
      if (key === 'content') {
        slotContent = newVal ?? '';
        previewEl = mountPreview(sandbox, comp, state, slotContent);
      } else {
        const prop = comp.props.find(p => p.attrName === key || p.name === key);
        if (newVal === null || newVal === undefined) {
          delete state[key];
          if (prop) applyPropToEl(previewEl, prop, null);
          else previewEl.removeAttribute(key);
        } else {
          state[key] = newVal;
          if (prop) applyPropToEl(previewEl, prop, newVal);
          else previewEl.setAttribute(key, String(newVal));
        }
      }
      updateSnippet();
    });
    controlsSection.appendChild(form);

    if (comp.events && comp.events.length) {
      const evtSection = document.createElement('div');
      evtSection.className = 'ts2-events-list';
      const evtTitle = document.createElement('h3');
      evtTitle.className = 'ts2-section-subtitle';
      evtTitle.textContent = 'Events';
      evtSection.appendChild(evtTitle);
      for (const evt of comp.events) {
        const row = document.createElement('div');
        row.className = 'ts2-event-field';
        const lbl = document.createElement('span');
        lbl.className = 'ts2-event-label';
        lbl.textContent = evt.name;
        row.appendChild(lbl);
        if (evt.description) {
          const desc = document.createElement('span');
          desc.className = 'ts2-event-value';
          desc.textContent = evt.description;
          row.appendChild(desc);
        }
        evtSection.appendChild(row);
      }
      controlsSection.appendChild(evtSection);
    }

    const resetBtn = document.createElement('pkts-button');
    resetBtn.setAttribute('label', 'Reset to defaults');
    resetBtn.setAttribute('variant', 'default');
    resetBtn.addEventListener('click', () => renderPanel(comp));
    controlsSection.appendChild(resetBtn);
  }

  mainCol.appendChild(controlsSection);
  mainCol.appendChild(snippetSection);
}

// ── Render component panel (dispatch) ─────────────────────────────────────────

function renderPanel(comp) {
  const avail = comp.availability;

  if (avail === 'html-native') {
    renderHtmlNativePanel(comp);
    return;
  }

  if (avail === 'ui-css') {
    if (comp.tagName) {
      renderUiCssWebPanel(comp);
    } else {
      renderUiCssNoWebPanel(comp);
    }
    return;
  }

  // 'web' or any unknown value
  renderWebPanel(comp);
}

// ── Sidebar ───────────────────────────────────────────────────────────────────

function buildSidebar(manifest) {
  const nav = document.getElementById('ts2-nav');
  nav.innerHTML = '';

  const controlsRow = document.createElement('div');
  controlsRow.className = 'ts2-sidebar-controls';

  const filterLabel = document.createElement('label');
  filterLabel.className   = 'ts2-filter-label';
  filterLabel.htmlFor     = 'ts2-avail-filter';
  filterLabel.textContent = 'Show:';

  const filterSel = document.createElement('select');
  filterSel.id        = 'ts2-avail-filter';
  filterSel.className = 'ts2-filter-select';
  for (const [val, text] of [
    ['all',         'All'],
    ['html-native', 'HTML native'],
    ['ui-css',      'ui-css'],
  ]) {
    const o = document.createElement('option');
    o.value = val;
    o.textContent = text;
    filterSel.appendChild(o);
  }

  controlsRow.appendChild(filterLabel);
  controlsRow.appendChild(filterSel);
  nav.appendChild(controlsRow);

  const catMap = new Map();
  for (const comp of manifest) {
    const cat = comp.category || 'Uncategorized';
    const sub = comp.subcategory || '';
    if (!catMap.has(cat)) catMap.set(cat, new Map());
    const subMap = catMap.get(cat);
    if (!subMap.has(sub)) subMap.set(sub, []);
    subMap.get(sub).push(comp);
  }

  for (const [cat, subMap] of catMap) {
    const details = document.createElement('details');
    details.className = 'ts2-nav-cat';
    details.dataset.category = cat;

    const summary = document.createElement('summary');
    summary.className = 'ts2-nav-cat-summary';
    summary.textContent = cat;
    details.appendChild(summary);

    for (const [sub, comps] of subMap) {
      const subgroup = document.createElement('div');
      subgroup.className = 'ts2-nav-subgroup';
      subgroup.dataset.subcat = sub;

      if (sub) {
        const subLabel = document.createElement('div');
        subLabel.className = 'ts2-nav-subcat';
        subLabel.textContent = sub;
        subgroup.appendChild(subLabel);
      }

      for (const comp of comps) {
        const avail = comp.availability || 'web';
        const a = document.createElement('a');
        a.href        = `#${comp.id || comp.tagName}`;
        a.className   = 'ts2-nav-item copy';
        a.dataset.tagName    = comp.id || comp.tagName;
        a.dataset.search     = comp.displayName.toLowerCase() + ' ' + (comp.id || comp.tagName);
        a.dataset.availability = avail;

        a.appendChild(document.createTextNode(comp.displayName));

        if (avail === 'html-native') {
          const chip = document.createElement('span');
          chip.className = 'ts2-avail-chip ts2-html-native-chip';
          chip.textContent = 'HTML native';
          a.appendChild(chip);
        } else if (avail === 'ui-css') {
          const chip = document.createElement('span');
          chip.className = 'ts2-avail-chip ts2-ui-css-chip';
          chip.textContent = 'ui-css';
          a.appendChild(chip);
        }
        // 'web': no chip

        subgroup.appendChild(a);
      }

      details.appendChild(subgroup);
    }

    nav.appendChild(details);
  }
}

// ── Active link + auto-expand ─────────────────────────────────────────────────

function setActiveLink(id) {
  document.querySelectorAll('.ts2-nav-item').forEach(a => {
    const isActive = a.dataset.tagName === id;
    a.classList.toggle('ts2-active', isActive);
    if (isActive) {
      const details = a.closest('details.ts2-nav-cat');
      if (details) details.open = true;
      a.scrollIntoView({ block: 'nearest' });
    }
  });
}

// ── Search ────────────────────────────────────────────────────────────────────

function initSearch() {
  const input = document.getElementById('ts2-search');
  if (!input) return;

  function applyVisibility() {
    const q      = input.value.trim().toLowerCase();
    const filter = document.getElementById('ts2-avail-filter')?.value ?? 'all';

    document.querySelectorAll('.ts2-nav-item').forEach(a => {
      const matchesSearch = !q || a.dataset.search.includes(q);
      const matchesFilter = filter === 'all' || a.dataset.availability === filter;
      a.classList.toggle('ts2-hidden', !(matchesSearch && matchesFilter));
    });

    document.querySelectorAll('.ts2-nav-subgroup').forEach(sg => {
      sg.style.display = sg.querySelectorAll('.ts2-nav-item:not(.ts2-hidden)').length > 0 ? '' : 'none';
    });

    document.querySelectorAll('.ts2-nav-cat').forEach(details => {
      const anyVisible = details.querySelectorAll('.ts2-nav-item:not(.ts2-hidden)').length > 0;
      details.style.display = anyVisible ? '' : 'none';
      if (q && anyVisible) details.open = true;
    });
  }

  input.addEventListener('input', applyVisibility);

  const filterSel = document.getElementById('ts2-avail-filter');
  if (filterSel) filterSel.addEventListener('change', applyVisibility);
}

// ── Router ────────────────────────────────────────────────────────────────────

function handleRoute(manifest) {
  const hash = location.hash.slice(1);
  const comp  = manifest.find(c => c.id === hash || c.tagName === hash) || manifest[0];
  if (!comp) return;
  renderPanel(comp);
  setActiveLink(comp.id || comp.tagName);
}

// ── Init ──────────────────────────────────────────────────────────────────────

const manifest = window.__PKTS_MANIFEST__;

if (!manifest) {
  document.getElementById('ts2-panel').innerHTML = `
    <div class="ts2-error">
      <h2>Manifest not found</h2>
      <p>Generate it first (from packages/ui-web):</p>
      <pre>npm run generate-manifest</pre>
      <p>Then reload this page.</p>
    </div>
  `;
} else {
  buildSidebar(manifest);
  initSearch();
  handleRoute(manifest);
  window.addEventListener('hashchange', () => handleRoute(manifest));

  if (typeof window.buildPalettePicker === 'function') {
    window.buildPalettePicker();
    window.applyPalette(localStorage.getItem('packets-palette') || 'default');
  }

  const toggle = document.getElementById('ts2-theme-toggle');
  if (toggle) {
    const cb = toggle.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = document.body.classList.contains('dark');
    toggle.addEventListener('change', () => {
      if (typeof window.toggleTheme === 'function') window.toggleTheme();
      const cb2 = toggle.querySelector('input[type="checkbox"]');
      if (cb2) cb2.checked = document.body.classList.contains('dark');
    });
  }
}
